text:
/* Foundation values: shared scales, independent of components and theme selection. */
:root {
  --neutral-0: #ffffff;
  --neutral-50: #fafafa;
  --neutral-100: #f3f4f6;
  --neutral-200: #e5e7eb;
  --neutral-300: #cbd0d8;
  --neutral-500: #687382;
  --neutral-700: #384252;
  --neutral-900: #20242b;
  --neutral-950: #0f1115;
  --font-mono: "SF Mono", Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  --font-sans: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --text-2xs: 9px;
  --text-xs: 10px;
  --text-sm: 11px;
  --text-md: 12px;
  --text-lg: 13px;
  --text-xl: 16px;
  --space-1: 2px;
  --space-2: 4px;
  --space-3: 6px;
  --space-4: 8px;
  --space-5: 10px;
  --space-6: 12px;
  --space-7: 14px;
  --space-8: 16px;
  --radius-none: 0px;
  --radius-sm: 3px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-panel: 7px;
  --radius-pill: 999px;
  --stroke-thin: 1px;
  --stroke-focus: 2px;
  --layer-theme-toggle: 9000;
  --layer-tooltip: 10000;
  --treemap-identity-opacity: 22%;
  --canvas-identity-opacity: 22%;
  --treemap-shade-shift: 0%;
}
